import assert from "node:assert/strict";
import { test } from "node:test";
import { decide } from "../screens/access.ts";
import { schema } from "../app/members/[memberId]/visits/page.schema.ts";

test("visits-form is refused to someone signed in without members.write", () => {
  assert.equal(decide(schema.permission, { signedIn: true, permissions: [] }), "refused");
});

test("visits-form sends someone signed out to sign in", () => {
  assert.equal(decide(schema.permission, { signedIn: false, permissions: [] }), "sign-in");
});

test("visits-form opens to someone who holds members.write", () => {
  assert.equal(decide(schema.permission, { signedIn: true, permissions: ["members.write"] }), "allowed");
});
